package deploy

// Purpose: stage the nginx/ tree of a v1.5 scratch build (D-0423, D-0424).
//          Only files this build generated ship, plus the files the operator
//          named in NSELF_DEPLOY_NGINX_INCLUDE. Everything else in the scratch
//          nginx/ tree (it was copied from the operator's project because the
//          build may read it) is left out and reported in ArtifactSet.NotShipped.
//          nginx/conf.d/<name>.conf ships when it was generated by this build;
//          no other conf.d path ever does.
// Inputs:  StageInput (scratch root, path map, stage dir) and its NginxPolicy.
// Outputs: the staged relative paths ("nginx/...") and the not-shipped ones.
// Constraints: "generated by this build" is decided by NginxPolicy.Generated on
//              the file head. The caller guarantees that a marker-carrying file
//              in the scratch tree was written by this build (the scratch copy
//              leaves marker-carrying nginx files behind), so the marker alone
//              proves it here. A nil policy ships every non-conf.d file and no
//              conf.d file (the behaviour before D-0423). The allowlist never
//              matches a conf.d* path: conf.d is governed by D-0424 only.

import (
	"fmt"
	"io"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
	"unicode"
)

// nginxHeadBytes is how much of a file head the policy sees.
const nginxHeadBytes = 128

// NginxPolicy says which scratch nginx/ files ship.
type NginxPolicy struct {
	// Generated reports whether a file head carries the generated marker of the
	// build (build.IsGeneratedNginxConf).
	Generated func(head []byte) bool
	// Include are validated allowlist globs relative to nginx/ (ParseNginxInclude).
	Include []string
}

// ParseNginxInclude parses the value of NSELF_DEPLOY_NGINX_INCLUDE: comma
// separated globs relative to nginx/, matched with path.Match per segment
// (`sites/hand.conf,includes/*.conf`). Blank entries are ignored. An entry that
// is absolute, not clean, holds a ".." segment, a control character or a bad
// pattern, or starts with conf.d fails the whole value: nothing is sent.
func ParseNginxInclude(raw string) ([]string, error) {
	var out []string
	for _, e := range strings.Split(raw, ",") {
		e = strings.TrimSpace(e)
		if e == "" {
			continue
		}
		switch {
		case strings.HasPrefix(e, "/") || filepath.IsAbs(e) || strings.Contains(e, `\`):
			return nil, fmt.Errorf("NSELF_DEPLOY_NGINX_INCLUDE entry %q is absolute; use a path relative to nginx/", e)
		case strings.ContainsFunc(e, unicode.IsControl):
			return nil, fmt.Errorf("NSELF_DEPLOY_NGINX_INCLUDE entry %q holds a control character", e)
		case e != path.Clean(e):
			return nil, fmt.Errorf("NSELF_DEPLOY_NGINX_INCLUDE entry %q is not a clean relative path", e)
		case strings.HasPrefix(e, "conf.d"):
			return nil, fmt.Errorf("NSELF_DEPLOY_NGINX_INCLUDE entry %q is under conf.d, which only files generated by this build may enter", e)
		}
		for _, seg := range strings.Split(e, "/") {
			if seg == ".." {
				return nil, fmt.Errorf("NSELF_DEPLOY_NGINX_INCLUDE entry %q holds ..", e)
			}
			if _, err := path.Match(seg, ""); err != nil {
				return nil, fmt.Errorf("NSELF_DEPLOY_NGINX_INCLUDE entry %q is not a valid glob: %w", e, err)
			}
		}
		out = append(out, e)
	}
	return out, nil
}

// allows reports whether rel (relative to nginx/, slash separated) matches an
// allowlist glob: same number of segments, each segment path.Match-ed. A conf.d*
// path never matches.
func (p *NginxPolicy) allows(rel string) bool {
	if p == nil || strings.HasPrefix(rel, "conf.d") {
		return false
	}
	segs := strings.Split(rel, "/")
	for _, g := range p.Include {
		gs := strings.Split(g, "/")
		if len(gs) != len(segs) {
			continue
		}
		ok := true
		for i := range gs {
			if m, err := path.Match(gs[i], segs[i]); err != nil || !m {
				ok = false
				break
			}
		}
		if ok {
			return true
		}
	}
	return false
}

// generated reports whether head carries the build marker under the policy.
func (p *NginxPolicy) generated(head []byte) bool {
	return p != nil && p.Generated != nil && p.Generated(head)
}

// readHead returns up to nginxHeadBytes of the file at p.
func readHead(p string) ([]byte, error) {
	f, err := os.Open(p)
	if err != nil {
		return nil, err
	}
	defer func() { _ = f.Close() }()
	buf := make([]byte, nginxHeadBytes)
	n, err := io.ReadFull(f, buf)
	if err != nil && err != io.EOF && err != io.ErrUnexpectedEOF {
		return nil, err
	}
	return buf[:n], nil
}

// stageNginx copies the shippable files of <ScratchRoot>/nginx into the stage
// dir (text rewritten to the remote layout) and returns their relative paths
// ("nginx/...") and the sorted relative paths it left out.
func stageNginx(in StageInput) (files, notShipped []string, err error) {
	root := filepath.Join(in.Map.ScratchRoot, "nginx")
	err = filepath.WalkDir(root, func(p string, d fs.DirEntry, werr error) error {
		if werr != nil {
			if os.IsNotExist(werr) && p == root {
				return filepath.SkipAll
			}
			return werr
		}
		sub, _ := filepath.Rel(root, p)
		sub = filepath.ToSlash(sub)
		if d.IsDir() {
			// conf.d is entered only as exactly nginx/conf.d, and only for its depth-1 files.
			if sub != "." && (strings.HasPrefix(sub, "conf.d/") || (strings.HasPrefix(d.Name(), "conf.d") && sub != "conf.d")) {
				return filepath.SkipDir
			}
			return nil
		}
		if !d.Type().IsRegular() {
			return nil
		}
		rel := path.Join("nginx", sub)
		confD := strings.HasPrefix(sub, "conf.d/")
		if confD && !isGeneratedConfD(rel) {
			return nil
		}
		head, herr := readHead(p)
		if herr != nil {
			return herr
		}
		ship := (in.Nginx == nil && !confD) || in.Nginx.generated(head) || (!confD && in.Nginx.allows(sub))
		if !ship {
			if !confD {
				notShipped = append(notShipped, rel)
			}
			return nil
		}
		data, rerr := readCapped(p)
		if rerr != nil {
			return rerr
		}
		dst := filepath.Join(in.StageDir, filepath.FromSlash(rel))
		if merr := os.MkdirAll(filepath.Dir(dst), 0o755); merr != nil {
			return merr
		}
		mode := os.FileMode(0o644)
		if info, ierr := d.Info(); ierr == nil {
			mode = info.Mode().Perm()
		}
		if werr := os.WriteFile(dst, []byte(in.Map.Rewrite(string(data))), mode); werr != nil {
			return werr
		}
		files = append(files, rel)
		return nil
	})
	sort.Strings(notShipped)
	return files, notShipped, err
}
